import uuid

import pytest
from sqlalchemy import func, select

from app.core.database import get_session_factory
from app.modules.jobs.models import Job, JobSchedule
from app.modules.jobs.schemas import JobStatus

pytestmark = [pytest.mark.db, pytest.mark.usefixtures("clean_database")]


def test_job_defaults_and_python_generated_uuid() -> None:
    with get_session_factory()() as session:
        job = Job(type="test.job", max_attempts=5)
        session.add(job)
        session.flush()

        # The id is generated by Python at flush; the database has no UUID default.
        assert isinstance(job.id, uuid.UUID)
        job_id = job.id
        session.commit()

    with get_session_factory()() as session:
        stored = session.scalars(select(Job).where(Job.id == job_id)).one()
        assert stored.status == JobStatus.QUEUED
        assert stored.payload == {}
        assert stored.attempts == 0
        assert stored.run_at is not None and stored.run_at.tzinfo is not None
        assert stored.created_at is not None and stored.updated_at is not None
        assert stored.finished_at is None
        assert stored.locked_by is None and stored.lease_expires_at is None


def test_each_job_gets_a_distinct_id() -> None:
    with get_session_factory()() as session:
        jobs = [Job(type="test.job", max_attempts=1) for _ in range(3)]
        session.add_all(jobs)
        session.commit()
        assert len({job.id for job in jobs}) == 3


def test_job_schedule_defaults() -> None:
    with get_session_factory()() as session:
        session.add(JobSchedule(name="s", job_type="test.job", interval_seconds=60, next_run_at=func.now()))
        session.commit()

        schedule = session.get(JobSchedule, "s")
        assert schedule is not None
        assert schedule.enabled is True
        assert schedule.payload == {}
        assert schedule.last_enqueued_at is None
